import { readFileSync, writeFileSync } from "node:fs";
const shell = readFileSync("mobile/assets/map-shell.html", "utf8");
const css = readFileSync("node_modules/leaflet/dist/leaflet.css", "utf8");
const js = readFileSync("node_modules/leaflet/dist/leaflet.js", "utf8").split(
  "//# sourceMappingURL",
)[0];
const html = shell
  .replace("__LEAFLET_CSS__", () => css)
  .replace("__LEAFLET_JS__", () => js);
writeFileSync(
  "mobile/src/map-document.ts",
  "// Leaflet 1.9.4, BSD-2-Clause; copyright Vladimir Agafonkin and contributors.\n// Generated by scripts/build-mobile-map.mjs.\nexport const mapDocument = " +
    JSON.stringify(html) +
    ";\n",
);
